import{rigNames}from'./rig-names.js';
import{finishTexture,prepareUV}from'./finishes.js';
import * as T from '../vendor/three.module.js';
export const shapeFields=['female','shoulders','chest','waist','abdomen','hips','pelvis','glutes','thighs','calves','headWidth','headDepth','jaw'];
const bell=(y,c,w)=>Math.exp(-(((y-c)/w)**2)),D=Math.PI/180;
export function shapePoint(p,s={}){let[x,y,z]=p;const f=k=>s[k]||0;const width=f('shoulders')*bell(y,1.43,.13)+f('chest')*bell(y,1.32,.12)+f('waist')*bell(y,1.13,.12)+f('hips')*bell(y,.94,.12)+f('pelvis')*bell(y,.87,.10)+f('thighs')*bell(y,.66,.18)+f('calves')*bell(y,.29,.16)+f('headWidth')*bell(y,1.74,.10)+f('jaw')*bell(y,1.65,.04);x*=1+width;z*=1+f('headDepth')*bell(y,1.74,.1)+f('chest')*bell(y,1.34,.12)*.5+f('pelvis')*bell(y,.87,.10)*.5;if(z>0)z+=f('abdomen')*.12*bell(y,1.13,.14);else z-=f('glutes')*.12*bell(y,.88,.10);return[x,y,z];}
export function topology(g){let h=2166136261;for(const n of g.index?.array||[])h=Math.imul(h^n,16777619)>>>0;return g.getAttribute('position').count+':'+h;}
export function surfaceController(records,bones={}){for(const r of records){r.base=r.mesh.geometry.getAttribute('position').array.slice();r.norm=r.mesh.geometry.getAttribute('normal').array.slice();r.index=topology(r.mesh.geometry);prepareUV(r.mesh.geometry);r.skin=r.mesh.geometry.getAttribute('skinIndex')?.array.slice();r.weights=r.mesh.geometry.getAttribute('skinWeight')?.array.slice();r.mesh.userData.surface=r.name;}let sig='';return n=>{const driven=(n.correctives||[]).map(c=>c.enabled===false?0:T.MathUtils.clamp(((bones[c.bone]?.rotation?.[c.axis]||0)/D-c.min)/(c.max-c.min),0,1));const k=JSON.stringify([driven,n.correctives,n.shape,n.sculpt,n.weights,n.parts?.shirt?.ease,n.parts?.trousers?.ease,n.parts?.shirt?.length]);if(k===sig)return;sig=k;for(const r of records){const g=r.mesh.geometry;r.index=topology(g);const p=g.getAttribute('position'),offsets=n.sculpt?.[r.name],valid=!offsets||offsets.topology===r.index;r.mesh.userData.editWarning=valid?'':'Surface topology changed: edits skipped';for(let i=0;i<p.count;i++){const v=shapePoint(Array.from(r.base.subarray(i*3,i*3+3)).map((v,c)=>v+(r.delta?.[i]?.[c]||0)*(n.shape?.female||0)),r.name.startsWith('hat-')?{}:n.shape),ease=n.parts?.[r.name]?.ease||0;for(let c=0;c<3;c++)v[c]+=r.norm[i*3+c]*ease+(valid?offsets?.vertices?.[i]?.[c]||0:0);for(let j=0;j<(n.correctives||[]).length;j++){const layer=n.correctives[j].surfaces?.[r.name];if(layer?.topology===r.index)for(let c=0;c<3;c++)v[c]+=(layer.vertices?.[i]?.[c]||0)*driven[j];}if(r.name==='shirt'&&v[1]<1.12)v[1]-=(n.parts?.shirt?.length||0)*Math.max(0,Math.min(1,(1.12-v[1])/.12));p.setXYZ(i,...v);}p.needsUpdate=true;g.computeVertexNormals();g.computeBoundingBox();g.computeBoundingSphere();if(r.mesh.isSkinnedMesh){r.mesh.boundingBox=null;r.mesh.boundingSphere=null;}if(r.skin){g.getAttribute('skinIndex').array.set(r.skin);g.getAttribute('skinWeight').array.set(r.weights);const w=n.weights?.[r.name];if(w?.topology===r.index)for(const[i,a]of Object.entries(w.vertices||{})){g.getAttribute('skinIndex').array.set(a.map(x=>x[0]),+i*4);g.getAttribute('skinWeight').array.set(a.map(x=>x[1]),+i*4);}g.getAttribute('skinIndex').needsUpdate=true;g.getAttribute('skinWeight').needsUpdate=true;}}};}
export function sculpt(n,mesh,index,{radius=.055,strength=.003,mirror=false,mode='inflate'}={}){const g=mesh.geometry,p=g.getAttribute('position'),normal=g.getAttribute('normal'),surface=mesh.userData.surface;if(!surface||index<0||index>=p.count)throw Error('Pick a valid surface vertex');n.sculpt??={};const entry=n.sculpt[surface]??={topology:topology(g),vertices:{}};if(entry.topology!==topology(g))throw Error('Topology mismatch');const center=new T.Vector3().fromBufferAttribute(p,index),centers=[center];if(mirror)centers.push(center.clone().multiply(new T.Vector3(-1,1,1)));let count=0;for(let i=0;i<p.count;i++){const v=new T.Vector3().fromBufferAttribute(p,i),d=Math.min(...centers.map(c=>c.distanceTo(v)));if(d>radius)continue;const old=entry.vertices[i]||[0,0,0],w=(1-d/radius)**2;entry.vertices[i]=old.map((x,c)=>T.MathUtils.clamp(x+(mode==='grabX'?(c===0?strength:0):normal.array[i*3+c]*strength*(mode==='deflate'?-1:1))*w,-.15,.15));count++;}return count;}
export function setWeight(n,mesh,index,bone,value){const g=mesh.geometry,si=g.getAttribute('skinIndex'),sw=g.getAttribute('skinWeight');if(!si||index<0||index>=si.count||!Number.isInteger(bone)||bone<0||bone>=mesh.skeleton.bones.length)throw Error('Invalid weight selection');const old=Array.from({length:4},(_,j)=>[si.array[index*4+j],sw.array[index*4+j]]).filter(x=>x[0]!==bone).sort((a,b)=>b[1]-a[1]).slice(0,3),sum=old.reduce((a,b)=>a+b[1],0);if(!sum)old.splice(0,old.length,[bone===0?1:0,1]);const total=old.reduce((a,b)=>a+b[1],0);let a=[[bone,value],...old.map(([b,w])=>[b,w/total*(1-value)])];while(a.length<4)a.push([0,0]);n.weights??={};const w=n.weights[mesh.userData.surface]??={topology:topology(g),vertices:{}};w.vertices[index]=a;return a;}
export function validateWorkshop(s){const num=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b,vec=v=>Array.isArray(v)&&v.length===3&&v.every(x=>num(x,-.15,.15));for(const n of s.nodes){for(const[k,v]of Object.entries(n.shape||{}))if(!shapeFields.includes(k)||!num(v,k==='female'?0:-.3,k==='female'?1:.3))throw Error('Invalid body shape');for(const v of Object.values(n.handCurl||{}))if(!num(v,0,1))throw Error('Invalid hand curl');for(const p of Object.values(n.parts||{})){for(const k of['clearcoat','sheen','clearcoatRoughness'])if(p[k]!==undefined&&!num(p[k],0,1))throw Error('Invalid physical material');if(p.ease!==undefined&&!num(p.ease,-.01,.05))throw Error('Invalid garment ease');if(p.length!==undefined&&!num(p.length,-.1,.15))throw Error('Invalid hem length');for(const k of['offsetX','offsetZ'])if(p[k]!==undefined&&!num(p[k],-.15,.15))throw Error('Invalid hat offset');if(p.autoFit!==undefined&&typeof p.autoFit!=='boolean')throw Error('Invalid auto fit');}for(const [surface,layer]of Object.entries(n.sculpt||{})){if(!['body','head','shirt','trousers','hat-brim','hat-crown','hat-band'].includes(surface)||typeof layer.topology!=='string'||Object.keys(layer.vertices||{}).length>12000)throw Error('Invalid sculpt layer');for(const[i,v]of Object.entries(layer.vertices||{}))if(!/^\d+$/.test(i)||+i>200000||!vec(v))throw Error('Invalid sculpt offset');}for(const layer of Object.values(n.weights||{})){if(typeof layer.topology!=='string'||Object.keys(layer.vertices||{}).length>12000)throw Error('Invalid weight layer');for(const[i,v]of Object.entries(layer.vertices||{}))if(!/^\d+$/.test(i)||+i>200000||!Array.isArray(v)||v.length!==4||v.some(a=>!Array.isArray(a)||a.length!==2||!Number.isInteger(a[0])||a[0]<0||a[0]>162||!num(a[1],0,1))||Math.abs(v.reduce((a,b)=>a+b[1],0)-1)>1e-5)throw Error('Invalid skin weights');}for(const bn of Object.keys(n.jointLimits||{}))if(!rigNames.includes(bn))throw Error('Unknown joint');for(const lim of Object.values(n.jointLimits||{}))for(const[a,r]of Object.entries(lim))if(!['x','y','z'].includes(a)||!Array.isArray(r)||r.length!==2||!r.every(v=>num(v,-180,180))||r[0]>r[1])throw Error('Invalid joint limit');for(const c of n.correctives||[]){if(!['x','y','z'].includes(c.axis)||!rigNames.includes(c.bone)||!num(c.min,-180,180)||!num(c.max,-180,180)||c.max<=c.min)throw Error('Invalid corrective driver');validateWorkshop({nodes:[{sculpt:c.surfaces}]});}if((n.correctives||[]).length>24)throw Error('Too many correctives');if(n.poseLibrary&&(!Array.isArray(n.poseLibrary)||n.poseLibrary.length>24))throw Error('Invalid pose library');if(n.attachment){const parent=s.nodes.find(p=>p.id===n.attachment.actor);if(n.type==='humanoid'||parent?.type!=='humanoid'||!rigNames.includes(n.attachment.bone))throw Error('Invalid bone attachment');}if(n.seatContact&&(!s.nodes.some(p=>p.id===n.seatContact.surface&&p.type==='box'&&!p.attachment)||!num(n.seatContact.clearance,0,.05)||!num(n.seatContact.startTime,0,s.duration)||!num(n.seatContact.endTime,n.seatContact.startTime,s.duration)))throw Error('Invalid seat contact');for(const c of Object.values(n.contacts||{})){if(!s.nodes.some(p=>p.id===c.surface&&['box','plane'].includes(p.type)&&!p.attachment)||!num(c.clearance,0,.25)||!Array.isArray(c.point)||c.point.length!==3||!c.point.every(v=>num(v,-.5,.5)))throw Error('Invalid surface contact');}}}
export function applyFinish(mat,p={}){for(const k of['clearcoat','clearcoatRoughness','sheen'])if(p[k]!==undefined){if((mat[k]>0)!==(p[k]>0))mat.needsUpdate=true;mat[k]=p[k];}mat.sheenColor?.set(p.color||mat.color);const map=finishTexture(p.finish);if(mat.bumpMap!==map){mat.bumpMap=map;mat.needsUpdate=true;}mat.bumpScale=p.bump??.001;}
export function limitJoints(n,map){for(const[name,limits]of Object.entries(n.jointLimits||{})){const b=map[name];if(b)for(const[axis,r]of Object.entries(limits))b.rotation[axis]=T.MathUtils.clamp(b.rotation[axis],r[0]*D,r[1]*D);}}
export function contactDefinition(n,objects){if(!n.contacts)return n;const o=structuredClone(n);o.ik??={};for(const[key,c]of Object.entries(n.contacts)){if(c.enabled===false)continue;const p=objects.get(c.surface);if(!p)continue;p.updateMatrixWorld(true);const point=p.localToWorld(new T.Vector3(...c.point)),normal=new T.Vector3(...(p.geometry?.type==='PlaneGeometry'?[0,0,1]:[0,1,0])).applyQuaternion(p.getWorldQuaternion(new T.Quaternion()));point.addScaledVector(normal,c.clearance);o.ik[key]={enabled:true,position:point.toArray()};}return o;}
export function seatOffset(character,seat,clearance=.005){seat.updateMatrixWorld(true);character.group.updateMatrixWorld(true);character.skeleton.update();const mesh=character.meshes.trousers,p=mesh.geometry.getAttribute('position'),inverse=seat.matrixWorld.clone().invert();let lowest=Infinity;for(let i=0;i<p.count;i+=2){if(p.getY(i)<.80||p.getY(i)>1.03)continue;const v=mesh.localToWorld(mesh.getVertexPosition(i,new T.Vector3())).applyMatrix4(inverse);if(Math.abs(v.x)<.5&&Math.abs(v.z)<.5)lowest=Math.min(lowest,v.y);}return Number.isFinite(lowest)?T.MathUtils.clamp((.5-lowest)*seat.getWorldScale(new T.Vector3()).y+clearance,-.4,.4):null;}
